function SbomForgePure(){
  // ==================== Package-URL (purl) ====================
  // 规范：pkg:type/namespace/name@version?qualifiers#subpath
  function dec(s){ try { return decodeURIComponent(s); } catch(e){ return s; } }
  function encSeg(s){
    return encodeURIComponent(String(s))
      .replace(/%3A/gi, ':').replace(/%2B/gi, '+')
      .replace(/'/g, '%27').replace(/\(/g, '%28').replace(/\)/g, '%29')
      .replace(/!/g, '%21').replace(/\*/g, '%2A');
  }
  // 需要小写 namespace + name 的类型
  var LOWER_NS_NAME = ['bitbucket','github','gitlab'];
  // 名称需小写的类型
  var LOWER_NAME = ['pypi','cran','composer','hex','npm','golang','conan','cargo','deb','rpm','apk'];

  function parsePurl(str){
    var s = String(str || '').trim();
    if (!s) return {error:'请输入 purl 字符串'};
    var subpath = '', qualifiers = {}, version = '', namespace = '', name = '', type = '';

    // 1) 从右侧切一次 '#'
    var hi = s.indexOf('#');
    if (hi >= 0){
      var sp = s.slice(hi + 1);
      s = s.slice(0, hi);
      var segs = sp.split('/').filter(function(x){ return x !== '' && x !== '.' && x !== '..'; });
      subpath = segs.map(dec).join('/');
    }
    // 2) 从右侧切一次 '?'
    var qi = s.indexOf('?');
    if (qi >= 0){
      var qs = s.slice(qi + 1);
      s = s.slice(0, qi);
      var pairs = qs.split('&');
      for (var i = 0; i < pairs.length; i++){
        if (!pairs[i]) continue;
        var eq = pairs[i].indexOf('=');
        if (eq < 0) return {error:'限定符缺少 “=”：' + pairs[i]};
        var k = pairs[i].slice(0, eq).toLowerCase();
        var v = dec(pairs[i].slice(eq + 1));
        if (v === '') continue;                    // 空值按规范丢弃
        if (k === 'checksums') qualifiers[k] = v.split(',');
        else qualifiers[k] = v;
      }
    }
    // 3) scheme
    var ci = s.indexOf(':');
    if (ci < 0) return {error:'缺少 “pkg:” 前缀'};
    var scheme = s.slice(0, ci).toLowerCase();
    if (scheme !== 'pkg') return {error:'scheme 必须是 pkg，当前为：' + scheme};
    s = s.slice(ci + 1).replace(/^\/+/, '');
    // 4) type
    var ti = s.indexOf('/');
    if (ti < 0) return {error:'缺少 type 与 name（形如 pkg:npm/left-pad）'};
    type = s.slice(0, ti).toLowerCase();
    if (!/^[a-z][a-z0-9.+-]*$/.test(type)) return {error:'type 不合法：' + type};
    s = s.slice(ti + 1);
    // 5) version（从右侧切一次 '@'）
    var ai = s.lastIndexOf('@');
    if (ai > 0){ version = dec(s.slice(ai + 1)); s = s.slice(0, ai); }
    // 6) namespace / name（从右侧切一次 '/'）
    var ni = s.lastIndexOf('/');
    if (ni >= 0){
      var nsRaw = s.slice(0, ni);
      name = dec(s.slice(ni + 1));
      namespace = nsRaw.split('/').filter(function(x){ return x !== ''; }).map(dec).join('/');
    } else {
      name = dec(s);
    }
    if (!name) return {error:'name 不能为空'};

    // 7) 类型专属规范化
    if (LOWER_NS_NAME.indexOf(type) >= 0){
      namespace = namespace.toLowerCase();
      name = name.toLowerCase();
    } else if (LOWER_NAME.indexOf(type) >= 0){
      name = name.toLowerCase();
    }
    if (type === 'pypi') name = name.replace(/_/g, '-');

    return {error:null, type:type, namespace:namespace, name:name,
            version:version, qualifiers:qualifiers, subpath:subpath};
  }

  function buildPurl(p){
    if (!p || !p.type || !p.name) return {error:'type 与 name 为必填'};
    var out = 'pkg:' + String(p.type).toLowerCase() + '/';
    if (p.namespace){
      out += String(p.namespace).split('/').filter(function(x){ return x !== ''; })
              .map(encSeg).join('/') + '/';
    }
    out += encSeg(p.name);
    if (p.version) out += '@' + encSeg(p.version);
    var q = p.qualifiers || {};
    var keys = Object.keys(q).filter(function(k){
      var v = q[k];
      return v !== '' && v !== null && v !== undefined && !(Array.isArray(v) && !v.length);
    }).sort();
    if (keys.length){
      out += '?' + keys.map(function(k){
        var v = q[k];
        if (Array.isArray(v)) v = v.join(',');
        return k.toLowerCase() + '=' + encSeg(v);
      }).join('&');
    }
    if (p.subpath){
      out += '#' + String(p.subpath).split('/').filter(function(x){ return x !== ''; })
                    .map(encSeg).join('/');
    }
    return {error:null, purl:out};
  }

  function normalizePurl(str){
    var p = parsePurl(str);
    if (p.error) return p;
    var b = buildPurl(p);
    if (b.error) return b;
    p.canonical = b.purl;
    return p;
  }

  // ==================== SBOM 解析 ====================
  function detectFormat(obj){
    if (!obj || typeof obj !== 'object') return null;
    if (obj.bomFormat === 'CycloneDX' || obj.specVersion && obj.components) return 'cyclonedx';
    if (obj.spdxVersion || obj.SPDXID) return 'spdx';
    return null;
  }

  function licOf(c){
    // CycloneDX: licenses:[{license:{id|name}}|{expression}]
    var out = [];
    var ls = c.licenses || [];
    for (var i = 0; i < ls.length; i++){
      var l = ls[i];
      if (l.expression) out.push(l.expression);
      else if (l.license) out.push(l.license.id || l.license.name || '');
    }
    return out.filter(function(x){ return x; });
  }

  function readCycloneDX(o){
    var comps = [];
    var root = (o.metadata && o.metadata.component) ? o.metadata.component : null;
    var list = o.components || [];
    function walk(arr){
      for (var i = 0; i < arr.length; i++){
        var c = arr[i];
        comps.push({
          ref: c['bom-ref'] || c.purl || (c.name + '@' + (c.version || '')),
          name: c.name || '', version: c.version || '', purl: c.purl || '',
          type: c.type || '', licenses: licOf(c),
          hashes: (c.hashes || []).map(function(h){ return h.alg + ':' + h.content; })
        });
        if (c.components && c.components.length) walk(c.components);
      }
    }
    walk(list);
    var deps = [];
    var dl = o.dependencies || [];
    for (var j = 0; j < dl.length; j++){
      var d = dl[j];
      var on = d.dependsOn || [];
      for (var k = 0; k < on.length; k++) deps.push({from: d.ref, to: on[k]});
    }
    return {
      format:'CycloneDX', spec: o.specVersion || '?', serial: o.serialNumber || '',
      subject: root ? (root.name + (root.version ? '@' + root.version : '')) : '',
      components: comps, deps: deps
    };
  }

  function readSPDX(o){
    var comps = [];
    var pkgs = o.packages || [];
    for (var i = 0; i < pkgs.length; i++){
      var p = pkgs[i];
      var purl = '';
      var refs = p.externalRefs || [];
      for (var r = 0; r < refs.length; r++){
        if (String(refs[r].referenceType || '').toLowerCase() === 'purl'){ purl = refs[r].referenceLocator || ''; break; }
      }
      var lics = [];
      [p.licenseConcluded, p.licenseDeclared].forEach(function(l){
        if (l && l !== 'NOASSERTION' && l !== 'NONE' && lics.indexOf(l) < 0) lics.push(l);
      });
      comps.push({
        ref: p.SPDXID || p.name, name: p.name || '', version: p.versionInfo || '',
        purl: purl, type: p.primaryPackagePurpose || '', licenses: lics,
        hashes: (p.checksums || []).map(function(h){ return h.algorithm + ':' + h.checksumValue; })
      });
    }
    var deps = [];
    var rl = o.relationships || [];
    for (var j = 0; j < rl.length; j++){
      var rel = rl[j];
      if (String(rel.relationshipType || '').toUpperCase().indexOf('DEPENDS_ON') >= 0)
        deps.push({from: rel.spdxElementId, to: rel.relatedSpdxElement});
    }
    return {
      format:'SPDX', spec: o.spdxVersion || '?', serial: o.documentNamespace || '',
      subject: o.name || '', components: comps, deps: deps
    };
  }

  function audit(sbom){
    var issues = [], c = sbom.components;
    var noVer = [], noLic = [], noPurl = [], noHash = [], badPurl = [];
    var seen = {}, dup = [];
    for (var i = 0; i < c.length; i++){
      var x = c[i];
      if (!x.version) noVer.push(x.name);
      if (!x.licenses.length) noLic.push(x.name);
      if (!x.purl) noPurl.push(x.name);
      else { var pp = parsePurl(x.purl); if (pp.error) badPurl.push(x.name + '（' + pp.error + '）'); }
      if (!x.hashes.length) noHash.push(x.name);
      var key = x.name + '@' + x.version;
      if (seen[key]) { if (dup.indexOf(key) < 0) dup.push(key); } else seen[key] = 1;
    }
    var refs = {};
    for (var j = 0; j < c.length; j++) refs[c[j].ref] = 1;
    var dangling = [];
    for (var k = 0; k < sbom.deps.length; k++){
      var d = sbom.deps[k];
      if (!refs[d.to] && dangling.indexOf(d.to) < 0) dangling.push(d.to);
    }
    function push(level, text, items){
      if (!items || !items.length) return;
      issues.push({level:level, text:text + '（' + items.length + '）',
                   detail: items.slice(0, 8).join('、') + (items.length > 8 ? ' …' : '')});
    }
    if (!sbom.subject) issues.push({level:'warn', text:'缺少顶层描述对象（metadata.component / document name）', detail:'难以判断这份 SBOM 描述的是哪个制品'});
    push('err',  '组件缺少版本号', noVer);
    push('err',  'purl 格式非法', badPurl);
    push('warn', '组件缺少许可证信息', noLic);
    push('warn', '组件缺少 purl 标识', noPurl);
    push('warn', '组件缺少哈希/校验和', noHash);
    push('warn', '重复的组件（同名同版本）', dup);
    push('err',  '依赖引用了不存在的组件', dangling);
    if (!c.length) issues.push({level:'err', text:'SBOM 中没有任何组件', detail:''});
    return issues;
  }

  function stats(sbom){
    var lic = {}, types = {};
    for (var i = 0; i < sbom.components.length; i++){
      var x = sbom.components[i];
      var ls = x.licenses.length ? x.licenses : ['(未声明)'];
      for (var j = 0; j < ls.length; j++) lic[ls[j]] = (lic[ls[j]] || 0) + 1;
      var t = '(未知)';
      if (x.purl){ var p = parsePurl(x.purl); if (!p.error) t = p.type; }
      types[t] = (types[t] || 0) + 1;
    }
    function top(o){
      return Object.keys(o).map(function(k){ return {k:k, n:o[k]}; })
        .sort(function(a, b){ return b.n - a.n || (a.k < b.k ? -1 : 1); });
    }
    return {licenses: top(lic), types: top(types)};
  }

  function analyze(text){
    var s = String(text || '').trim();
    if (!s) return {error:'请粘贴 CycloneDX 或 SPDX 的 JSON 内容'};
    var o;
    try { o = JSON.parse(s); } catch(e){ return {error:'JSON 解析失败：' + e.message}; }
    var fmt = detectFormat(o);
    if (!fmt) return {error:'无法识别的 SBOM 格式（需要 CycloneDX 的 bomFormat 或 SPDX 的 spdxVersion 字段）'};
    var sbom = (fmt === 'cyclonedx') ? readCycloneDX(o) : readSPDX(o);
    sbom.error = null;
    sbom.issues = audit(sbom);
    sbom.stats = stats(sbom);
    sbom.errCount = sbom.issues.filter(function(x){ return x.level === 'err'; }).length;
    return sbom;
  }

  var api = {parsePurl:parsePurl, buildPurl:buildPurl, normalizePurl:normalizePurl,
             analyze:analyze, detectFormat:detectFormat, audit:audit, stats:stats,
             readCycloneDX:readCycloneDX, readSPDX:readSPDX};
  if (typeof window !== 'undefined'){ window.__PURE__ = api; }
  if (typeof module !== 'undefined' && module.exports){ module.exports = {SbomForgePure:SbomForgePure}; }
  return api;
}
